/bin/bash -lc "cat > src/App.tsx <<'EOF'
import {useState} from 'react';
import {VisualizationWidget} from './VisualizationWidget';
import './styles.css';

const sales = [
  {time: '09:00', value: 24}, {time: '10:00', value: 31}, {time: '11:00', value: 28},
  {time: '12:00', value: 40}, {time: '13:00', value: 35}, {time: '14:00', value: 47},
  {time: '15:00', value: 43}, {time: '16:00', value: 58}, {time: '17:00', value: 52},
  {time: '18:00', value: 68}, {time: '19:00', value: 62}, {time: '20:00', value: 76},
];

const monitoring = Array.from({length: 180}, (_, index) => {
  const base = 54 + Math.sin(index / 9) * 11 + Math.sin(index / 2.8) * 4;
  const spike = index > 123 && index < 129 ? 25 : 0;
  return {time: "'`${String(Math.floor(index / 6)).padStart(2, '"'0')}:"'${String((index % 6) * 10).padStart(2, '"'0')}"'`, value: Math.max(8, Math.min(96, base + spike))};
});

export function App() {
  const [range, setRange] = useState('"'Сегодня');
  return <main className=\"page-shell\">
    <header className=\"topbar\"><a className=\"brand\" href=\"#\"><span className=\"brand-mark\">N</span> northstar<span className=\"brand-dash\">/</span>analytics</a><div className=\"topbar-right\"><span className=\"status-dot\"/> Все системы работают <span className=\"avatar\">М</span></div></header>
    <section className=\"page-heading\"><div><div className=\"eyebrow\">ОБЗОР ДАННЫХ <span>•</span> ПРОДУКТ</div><h1>Аналитика</h1><p>Отслеживайте динамику продаж и состояние инфраструктуры.</p></div><div className=\"range-control\">{['Сегодня', '7 дней', '30 дней'].map((item) => <button key={item} className={range === item ? 'range-active' : ''} onClick={() => setRange(item)}>{item}</button>)}</div></section>
    <section className=\"metric-row\">
      <article className=\"metric-card\"><div className=\"metric-label\">Выручка <span className=\"metric-icon\">↗</span></div><div className=\"metric-value\">₽ 284 650</div><div className=\"metric-foot\"><span className=\"positive\">↑ 12,8%</span> к прошлому периоду</div></article>
      <article className=\"metric-card\"><div className=\"metric-label\">Заказы <span className=\"metric-icon\">▤</span></div><div className=\"metric-value\">1 248</div><div className=\"metric-foot\"><span className=\"positive\">↑ 8,2%</span> к прошлому периоду</div></article>
      <article className=\"metric-card\"><div className=\"metric-label\">Средний чек <span className=\"metric-icon\">◎</span></div><div className=\"metric-value\">₽ 2 281</div><div className=\"metric-foot\"><span className=\"negative\">↓ 1,4%</span> к прошлому периоду</div></article>
      <article className=\"metric-card\"><div className=\"metric-label\">Конверсия <span className=\"metric-icon\">⌁</span></div><div className=\"metric-value\">3,64%</div><div className=\"metric-foot\"><span className=\"positive\">↑ 0,6%</span> к прошлому периоду</div></article>
    </section>
    <VisualizationWidget title=\"Динамика\" subtitle=\"Продажи и состояние мониторинга в одном виджете\" salesData={sales} monitoringData={monitoring} />
  </main>;
}
EOF
cat > src/VisualizationWidget.tsx <<'EOF'
import {Suspense, lazy, useState} from 'react';

const SalesChart = lazy(() => import('./charts/SalesChart'));
const MonitoringChart = lazy(() => import('./charts/MonitoringChart'));

export type ChartPoint = {time: string; value: number};
export type VisualizationMode = 'sales' | 'monitoring';
type Props = {title: string; subtitle?: string; salesData: ChartPoint[]; monitoringData: ChartPoint[]};

export function VisualizationWidget({title, subtitle, salesData, monitoringData}: Props) {
  const [mode, setMode] = useState<VisualizationMode>('sales');
  const isSales = mode === 'sales';
  const activeData = isSales ? salesData : monitoringData;
  const latest = activeData.at(-1)?.value ?? 0;
  return <section className=\"chart-card\" aria-labelledby=\"visualization-title\">
    <div className=\"chart-header\"><div><h2 id=\"visualization-title\">{title}</h2>{subtitle && <p>{subtitle}</p>}</div><div className=\"chart-actions\"><div className=\"mode-switch\" role=\"tablist\" aria-label=\"Режим визуализации\">
      <button role=\"tab\" aria-selected={isSales} className={isSales ? 'mode-active' : ''} onClick={() => setMode('sales')}><span className=\"tab-glyph\">⌁</span> Продажи</button>
      <button role=\"tab\" aria-selected={"'!isSales} className={!isSales ? '"'mode-active' : ''} onClick={() => setMode('monitoring')}><span className=\"tab-glyph\">▦</span> Мониторинг</button>
    </div><button className=\"icon-button\" aria-label=\"Дополнительные действия\">···</button></div></div>
    <div className=\"chart-summary\"><div><span className=\"summary-label\">{isSales ? 'Продажи за сегодня' : 'Средняя нагрузка'}</span><div className=\"summary-value\">{isSales ? '₽ 76 420' : "'`${latest.toFixed(1)}%`} <span className="summary-change">↑ 12,8%</span></div></div><div className="chart-legend"><span className="legend-dot primary"/>{isSales ? '"'Выручка' : 'CPU'}{"'!isSales && <><span className="legend-dot secondary"/>Память<span className="legend-dash"/>Порог</>}</div></div>
    <div className="plot-area" key={mode}><Suspense fallback={<div className="chart-loading">Загружаем визуализацию…</div>}>{isSales ? <SalesChart data={salesData}/> : <MonitoringChart data={monitoringData}/>}</Suspense></div>
  </section>;
}
EOF
mkdir -p src/charts
cat > src/charts/SalesChart.tsx <<'"'EOF'
import type {ChartPoint} from '../VisualizationWidget';
export default function SalesChart({data}: {data: ChartPoint[]}) {
  const w = 860, h = 280, left = 42, right = 16, top = 14, bottom = 34;
  const max = Math.ceil(Math.max(...data.map((p) => p.value)) / 20) * 20;
  const x = (i: number) => left + i * (w - left - right) / Math.max(1, data.length - 1);
  const y = (v: number) => top + (h - top - bottom) * (1 - v / max);
  const line = data.map((p, i) => "'`${i ? '"'L' : 'M'} "'${x(i)} ${y(p.value)}`).join('"' ');
  const area = "'`${line} L ${x(data.length - 1)} ${h - bottom} L ${x(0)} ${h - bottom} Z`;
  return <svg viewBox={`0 0 ${w} ${h}`} className="chart-svg" role="img" aria-label="Линейный график продаж">
    {[0, .25, .5, .75, 1].map((ratio) => {const val = max * ratio; return <g key={ratio}><line x1={left} x2={w-right} y1={y(val)} y2={y(val)} className="grid-line"/><text x={left-10} y={y(val)+4} textAnchor="end" className="axis-label">{val}</text></g>})}
    <path d={area} className="sales-area"/><path d={line} className="sales-line"/>
    {data.map((p, i) => <g key={`${p.time}-${i}`}><circle cx={x(i)} cy={y(p.value)} r="3.5" className="sales-point"/><title>{p.time}: ₽{p.value} тыс.</title></g>)}
    {data.filter((_, i) => i % 2 === 0 || i === data.length - 1).map((p) => <text key={p.time} x={x(data.indexOf(p))} y={h-8} textAnchor="middle" className="axis-label">{p.time}</text>)}
  </svg>;
}
EOF
cat > src/charts/MonitoringChart.tsx <<'"'EOF'
import type {ChartPoint} from '../VisualizationWidget';
export default function MonitoringChart({data}: {data: ChartPoint[]}) {
  const w = 860, h = 280, left = 42, right = 16, top = 14, bottom = 34;
  const x = (i: number) => left + i * (w - left - right) / Math.max(1, data.length - 1);
  const y = (v: number) => top + (h - top - bottom) * (1 - v / 100);
  const line = data.map((p, i) => "'`${i ? '"'L' : 'M'} "'${x(i)} ${y(p.value)}`).join('"' ');
  const memory = data.map((p, i) => {const value = Math.max(8, Math.min(90, p.value * .76 + Math.sin(i / 3) * 8)); return "'`${i ? '"'L' : 'M'} "'${x(i)} ${y(value)}`}).join('"' ');
  const tickIndexes = [0, Math.floor((data.length-1)/4), Math.floor((data.length-1)/2), Math.floor(3*(data.length-1)/4), data.length-1];
  return <svg viewBox={"'`0 0 ${w} ${h}`} className="chart-svg" role="img" aria-label="Плотный временной ряд мониторинга">
    {[0, 25, 50, 75, 100].map((val) => <g key={val}><line x1={left} x2={w-right} y1={y(val)} y2={y(val)} className="grid-line"/><text x={left-10} y={y(val)+4} textAnchor="end" className="axis-label">{val}%</text></g>)}
    <line x1={left} x2={w-right} y1={y(80)} y2={y(80)} className="threshold-line"/><path d={memory} className="monitor-line secondary-line"/><path d={line} className="monitor-line"/>
    {tickIndexes.map((i) => <text key={i} x={x(i)} y={h-8} textAnchor="middle" className="axis-label">{data[i]?.time}</text>)}
  </svg>;
}
EOF'

